  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = async (items) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  return { status: res.status, body: await res.json() }
}
const totalOf = async (items) => (await post(items)).body.total

test('no discount at or below 100 (threshold is strict >)', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100)
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 100)
})

test('10% discount applies once raw total exceeds 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
  assert.equal(await totalOf([{ sku: 'A', qty: 20 }]), 180)
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 90) // 101 -> 90.9 floored
})

test('discount cliff: a larger order can cost less than a smaller one', async () => {
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 100)
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99)
})

test('total is floored to whole euros, not rounded (cents are dropped)', async () => {
  assert.equal(await totalOf([{ sku: 'C', qty: 3 }]), 0) // 0.30000000000000004
  assert.equal(await totalOf([{ sku: 'B', qty: 1 }]), 25) // 25.5
  assert.equal(await totalOf([{ sku: 'D', qty: 3 }]), 99) // 99.99
  assert.equal(await totalOf([{ sku: 'D', qty: 4 }]), 119) // 133.32*0.9 = 119.988
})

test('multiple lines are summed before the discount', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 5 }, { sku: 'B', qty: 2 }]), 100) // 101 -> 90.9? see below
})

test('response shape and persistence via GET', async () => {
  const { status, body } = await post([{ sku: 'A', qty: 2 }])
  assert.equal(status, 201)
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof body.id, 'string')
  const got = await (await fetch(`${base}/orders/${body.id}`)).json()
  assert.deepEqual(got, body)
})

test('quirks: unknown order returns 200, bad input 400, unknown route 404', async () => {
  const res = await fetch(`${base}/orders/nope`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
  assert.equal((await post([])).status, 400)
  assert.equal((await fetch(`${base}/x`)).status, 404)
})

test('quirks: unknown sku / negative qty are not validated', async () => {
  assert.equal(await totalOf([{ sku: 'ZZ', qty: 1 }]), null) // NaN serialises as null
  assert.equal(await totalOf([{ sku: 'A', qty: -2 }]), -20)
})
